#: Statuses that existed before the one-step flow (no approval stage).
PRE_APPROVAL = ["draft", "pending_approval", "approved"]


def activate_pre_approval_loans(apps, schema_editor):
    """Loans still waiting for approval become live from their application date."""
    Loan = apps.get_model("loans", "Loan")
    Installment = apps.get_model("loans", "Installment")
    today = timezone.localdate()
    for loan in Loan.objects.filter(status__in=PRE_APPROVAL).select_related("business"):
        cutoff = today - dt.timedelta(days=loan.business.grace_days or 0)
        has_overdue = (
            Installment.objects.filter(loan=loan, due_date__lt=cutoff)
            .exclude(status="paid").exists()
        )
        if loan.outstanding_balance <= 0:
            loan.status = "settled"
        else:
            loan.status = "past_due" if has_overdue else "active"
        loan.disbursement_date = (
            loan.disbursement_date or loan.approval_date or loan.application_date)
        loan.disbursed_by_id = (
            loan.disbursed_by_id or loan.approved_by_id or loan.created_by_id)
        loan.save(update_fields=["status", "disbursement_date", "disbursed_by"])


